16	// Any real, visible focusable content a mega-menu panel can contain (leaf links; a bare
17	// <button> never occurs there today, included for robustness) — see focusFirstPanelLink below.
18	const PANEL_FOCUSABLE_SELECTOR = 'a[href], button:not([disabled])';
