27	/**
28	 * Enabling a CSS `transition` and changing the property it targets in the same React commit
29	 * gives the browser no prior painted frame to interpolate from — it snaps straight to the
30	 * target with zero animation and no `transitionend`, which stalls useMegaMenuMotion's phase
31	 * machine forever waiting on a completion event that never comes (confirmed empirically:
32	 * grid-template-rows reached its final value within 50ms with no interpolation).
33	 *
34	 * Fix: defer the value change by two `requestAnimationFrame`s whenever it should animate (one
35	 * rAF isn't reliably enough to cross a real paint boundary), so the transition is already
36	 * active on a genuine prior frame before the target changes. Applies instantly otherwise.
37	 */
38	const useTransitionSafeValue = <TValue,>(target: TValue, shouldAnimate: boolean, initial: TValue): TValue => {
39	  const [value, setValue] = useState(initial);
40	
41	  useLayoutEffect(() => {
42	    if (!shouldAnimate) {
43	      setValue(target);
44	      return undefined;
45	    }
46	    let secondFrame = 0;
47	    const firstFrame = requestAnimationFrame(() => {
48	      secondFrame = requestAnimationFrame(() => setValue(target));
49	    });
50	    return () => {
51	      cancelAnimationFrame(firstFrame);
52	      if (secondFrame) cancelAnimationFrame(secondFrame);
53	    };
54	  }, [target, shouldAnimate]);
55	
56	  return value;
57	};
