112	  contentComponent,
113	  item,
114	  name,
115	  itemsKey,
116	  maxColumns,
117	  isOpen,
118	  onOpen,
119	  onClose,
120	  isActiveItem,
121	  isTriggerActive,
122	  motionPhase,
123	  onExpandComplete,
124	  onContentInComplete,
125	  onContentOutComplete,
126	  onCollapseComplete,
127	  triggerRef,
