1	import React, { useEffect } from 'react';
2	import { Box, Center, Flex, Spinner, Stack, useTheme } from '@salesforce/retail-react-app/app/components/shared/ui';
3	import { ListMenuPopover } from './list-menu-popover';
4	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
5	import { MegaMenuContent } from 'app/components/list-menu/megaMenuContent';
6	import { useHeaderNav } from 'app/hooks/useHeaderNav';
7	import { useUiCopy } from 'app/hooks/useUiCopy';
8	import { useMegaMenuOpenReporter } from 'app/hooks/useMegaMenuOpenReporter';
9	import { useMegaMenuMotion } from 'app/hooks/useMegaMenuMotion';
10	import { useHeaderNavKeyboard } from 'app/hooks/useHeaderNavKeyboard';
11	import type { HeaderNavItemEntry } from 'app/types/contentful';
12	
13	const MAXIMUM_NUMBER_COLUMNS = 5;
14	
15	// headerNavItem's mega-menu columns live under `fields.columns`, not base SFCC's 'categories'
16	// default — ListMenuPopover/ListMenuContent index into `item[itemsKey]` generically.
17	const HEADER_NAV_ITEMS_KEY = 'columns';
18	
19	type ListMenuViewProps = {
20	  /** Region-resolved header nav items, or undefined while loading (see useHeaderNav.ts). */
21	  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
22	  isLoading: boolean;
23	  maxColumns?: number;
24	};
25	
26	/** Header desktop nav — presentational. Receives resolved `headerNavItem` entries as props and
27	 *  fetches nothing itself, matching the Footer/FooterContainer split — `ListMenu` below is this
28	 *  component's container.
29	 *
30	 * @param props see ListMenuViewProps
31	 */
32	export const ListMenuView = ({ items, isLoading, maxColumns = MAXIMUM_NUMBER_COLUMNS }: ListMenuViewProps) => {
33	  // components.ListMenu is dynamically registered and has no static type — cast unavoidable.
34	  const { components } = useTheme() as {
35	    components: Record<string, { baseStyle: Record<string, Record<string, unknown>> }>;
36	  };
37	  const { t } = useUiCopy();
38	  const { baseStyle } = components.ListMenu;
39	
40	  // Single shared "which L1 item is open, and what motion phase it's in" source of truth — see
41	  // useMegaMenuMotion's own JSDoc for the open/switch/close choreography.
42	  const {
43	    activeItemId,
44	    pendingItemId,
45	    phase,
46	    hover,
47	    close,
48	    onExpandComplete,
49	    onContentInComplete,
50	    onContentOutComplete,
51	    onCollapseComplete,
52	  } = useMegaMenuMotion();
53	
54	  // Reports the *list's* open/close state up to the header shell once here, rather than each
55	  // MegaMenuContent instance reporting its own isOpen — that used to race when switching
56	  // directly between items. `close` (not a raw state setter) is reported so RightBar's Close
57	  // control triggers the same fade-out-then-collapse sequence as any other close.
58	  const { reportOpen, reportClose } = useMegaMenuOpenReporter();
59	  useEffect(() => {
60	    if (activeItemId) {
61	      reportOpen(close);
62	    } else {
63	      reportClose();
64	    }
65	  }, [activeItemId, close, reportOpen, reportClose]);
66	
67	  // The most recently *hovered* item — unlike activeItemId (which stays on the outgoing item
68	  // throughout a switch's fade-out), this changes instantly, so both L1 triggers' underlines
69	  // animate concurrently instead of the old one waiting for the switch to finish.
70	  const targetItemId = pendingItemId ?? activeItemId;
71	
72	  // Left/Right/Home/End roving focus across the L1 triggers below — supplementary to native Tab
73	  // order, not a replacement for it. See useHeaderNavKeyboard.ts.
74	  const { getTriggerRef, onTriggerKeyDown } = useHeaderNavKeyboard();
75	
76	  return (
77	    <nav id="list-menu" aria-label={t('list_menu.nav.assistive_msg', 'Main navigation')} aria-busy={isLoading}>
78	      {/* display="flex" overrides SFCC's display:{base:'none',lg:'flex'}; paddingLeft={0}
79	          removes SFCC's 4-unit offset (content padding lives in header.ts instead). */}
80	      <Flex {...baseStyle.container} display="flex" alignItems="center" paddingLeft={0}>
81	        {items ? (
82	          <Stack direction="row" {...baseStyle.stackContainer} gap="var(--zimm-scale-3xl)">
83	            {items.map((item, index) => {
84	              const { id } = item.sys;
85	              const { label, href, columns = [] } = item.fields;
86	              const itemsCount = columns.length;
87	
88	              return (
89	                <Box key={id}>
90	                  {itemsCount > 0 ? (
91	                    <ListMenuPopover
92	                      key={id}
93	                      maxColumns={maxColumns}
94	                      item={item}
95	                      name={label}
96	                      itemsKey={HEADER_NAV_ITEMS_KEY}
97	                      contentComponent={MegaMenuContent}
98	                      // True for both the outgoing and incoming item during a switch — lets the
99	                      // incoming item's Popover pre-position before it visually takes over (see
100	                      // list-menu-popover.tsx's isActiveItem doc comment).
101	                      isOpen={activeItemId === id || pendingItemId === id}
102	                      isActiveItem={activeItemId === id}
103	                      isTriggerActive={targetItemId === id}
104	                      motionPhase={phase}
105	                      onOpen={() => hover(id)}
106	                      onClose={close}
107	                      onExpandComplete={onExpandComplete}
108	                      onContentInComplete={onContentInComplete}
109	                      onContentOutComplete={onContentOutComplete}
110	                      onCollapseComplete={onCollapseComplete}
111	                      triggerRef={getTriggerRef(index)}
112	                      onTriggerKeyDown={onTriggerKeyDown(index)}
113	                    />
114	                  ) : (
115	                    <ZimmNavItem
116	                      label={label}
117	                      href={href}
118	                      growUnderline
119	                      ref={getTriggerRef(index)}
120	                      onKeyDown={onTriggerKeyDown(index)}
121	                    />
122	                  )}
123	                </Box>
124	              );
125	            })}
126	          </Stack>
127	        ) : (
128	          // Scoped to just this loading indicator, not the whole nav (see the removed
129	          // aria-live/aria-atomic above) — Chakra's Spinner carries its own visually-hidden
130	          // "Loading..." label, so this announces once, atomically, when it appears. Wrapping
131	          // the *entire* nav in aria-live+aria-atomic instead (the previous shape of this code)
132	          // re-announced this whole subtree — every mega-menu link, plus the promo image's alt
133	          // text — on every later, unrelated mutation inside it (e.g. a mega menu's own opening
134	          // animation updating an inline style), which is what produced the "screen reader reads
135	          // everything at once" bug. A live region that large has no natural target text and no
136	          // matching mutation to react to that a shopper would actually want announced.
137	          <Center p="2" aria-live="polite" aria-atomic="true">
138	            <Spinner size="lg" />
139	          </Center>
140	        )}
141	      </Flex>
142	    </nav>
143	  );
144	};
