146	ListMenuView.displayName = 'ListMenuView';
147	
148	type ListMenuProps = {
149	  /** Accepted only for call-site compatibility with base `_app.jsx`'s SFCC category-tree
150	   *  contract. `ListMenu` self-fetches its own data via `useHeaderNav()`, so all of these are
151	   *  ignored except `maxColumns`. */
152	  root?: Record<string, unknown>;
153	  contentComponent?: React.ElementType;
154	  itemsKey?: string;
155	  itemsCountKey?: string;
156	  maxColumns?: number;
157	};
158	
159	/** Header desktop nav — container. Fetches `headerNavItem` entries via `useHeaderNav()` and
160	 *  renders `ListMenuView` with the result.
161	 *
162	 * @param props see ListMenuProps
163	 */
164	const ListMenu = ({ maxColumns }: ListMenuProps) => {
165	  const { items, isLoading } = useHeaderNav();
166	
167	  return <ListMenuView items={items} isLoading={isLoading} maxColumns={maxColumns} />;
168	};
169	
170	ListMenu.displayName = 'ListMenu';
171	
172	export { ListMenu };
