1	import React, { useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { IconButton } from '@salesforce/retail-react-app/app/components/shared/ui';
4	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
5	import { getSessionJSONItem, setSessionJSONItem } from '@salesforce/retail-react-app/app/utils/utils';
6	import { RECENT_SEARCH_KEY, RECENT_SEARCH_LIMIT } from '@salesforce/retail-react-app/app/constants';
7	import { searchUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
8	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
9	import { useUiCopy } from 'app/hooks/useUiCopy';
10	
11	type ZimmSearchInputProps = {
12	  /** Forwarded to the native input for programmatic focus control. */
13	  inputRef?: React.Ref<HTMLInputElement>;
14	  /** Placeholder text shown in the default state. Rendered uppercase via CSS. Defaults to
15	   *  useUiCopy()'s `header.field.placeholder.search` entry when omitted. */
16	  placeholder?: string;
17	};
18	
19	/**
20	 * Search input atom — 180×24px underline-style field.
21	 *
22	 * Default state: placeholder "SEARCH" label with bottom border.
23	 * Active state (has value): typed text + clear (×) button positioned absolutely.
24	 *
25	 * Adapts core search behaviour from the base SFCC Search component:
26	 *   - Navigates to the search results page on Enter (useNavigation + searchUrlBuilder).
27	 *   - Saves the submitted term to session recent-search history (capped at RECENT_SEARCH_LIMIT).
28	 *   - Clear (×) button resets the field without submitting.
29	 *   - Suggestions UI (useSearchSuggestions popover) is Sprint 3 work — Squad B scope.
30	 *
31	 * Figma: nodes 40000259:10763 (default), 40000259:13094 (active),
32	 *        40000259:13091 (clear icon, 16×16px at right edge).
33	 *
34	 * @param props.inputRef - Forwarded to the native input for programmatic focus.
35	 * @param props.placeholder - Placeholder text; rendered uppercase via CSS.
36	 */
37	export const ZimmSearchInput = ({ inputRef, placeholder }: ZimmSearchInputProps) => {
38	  const styles = useMultiStyleConfig('ZimmSearchInput');
39	  const [value, setValue] = useState('');
40	  const navigate = useNavigation();
41	  const { t } = useUiCopy();
42	  const resolvedPlaceholder = placeholder ?? t('header.field.placeholder.search', 'Search');
43	
44	  const saveRecentSearch = (searchText: string) => {
45	    // getSessionJSONItem returns whatever JSON currently sits under the key — validate the
46	    // shape rather than asserting it, so a corrupted or unexpected stored value can't throw
47	    // here (see .filter/.toLowerCase below).
48	    const stored: unknown = getSessionJSONItem(RECENT_SEARCH_KEY);
49	    const current = Array.isArray(stored) ? stored.filter((s): s is string => typeof s === 'string') : [];
50	    const deduped = current.filter((s) => s.toLowerCase() !== searchText.toLowerCase());
51	    setSessionJSONItem(RECENT_SEARCH_KEY, [searchText, ...deduped].slice(0, RECENT_SEARCH_LIMIT));
52	  };
53	
54	  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
55	    e.preventDefault();
56	    const searchText = value.trim();
57	    if (!searchText) return;
58	    saveRecentSearch(searchText);
59	    navigate(searchUrlBuilder(searchText));
60	  };
61	
62	  return (
63	    // chakra.form: applies container recipe styles (position:relative, 180×24px, border-bottom)
64	    // on a <form> element so pressing Enter submits without a separate submit button.
65	    // The clear IconButton carries type="button" to prevent accidental form submission.
66	    <chakra.form __css={styles.container} onSubmit={handleSubmit}>
67	      <chakra.input
68	        __css={styles.input}
69	        ref={inputRef as React.Ref<HTMLInputElement>}
70	        type="search"
71	        value={value}
72	        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setValue(e.target.value)}
73	        placeholder={resolvedPlaceholder}
74	        aria-label={resolvedPlaceholder}
75	        // When value is present, reserve right space: 16px icon + 8px gap (--zimm-scale-200).
76	        // Matches Figma active state: text width 156px = 180px - 8px gap - 16px icon.
77	        paddingRight={value ? 'calc(var(--zimm-icon-size-md) + var(--zimm-scale-200))' : 0}
78	      />
79	      {value && (
80	        // IconButton matches the proven centering pattern from the header icon buttons:
81	        // display/alignItems/justifyContent as direct props ensure flex layout is applied
82	        // regardless of Chakra's Button base or unstyled-variant styles.
83	        // minHeight/height="auto" let top:0+bottom:0 span the full container height.
84	        <IconButton
85	          aria-label={t('header.button.assistive_msg.clear_search', 'Clear search')}
86	          icon={<ZimmIcon type="close" size="md" aria-hidden={true} />}
87	          variant="unstyled"
88	          type="button"
89	          position="absolute"
90	          top={0}
91	          bottom={0}
92	          right={0}
93	          width="var(--zimm-icon-size-md)"
94	          minWidth="unset"
95	          height="auto"
96	          minHeight="unset"
97	          display="flex"
98	          alignItems="center"
99	          justifyContent="center"
100	          padding={0}
101	          onClick={() => setValue('')}
102	          color="var(--zimm-color-text-default)"
103	          _focusVisible={{
104	            outline: 'var(--zimm-focus-ring)',
105	            outlineOffset: 'var(--zimm-focus-ring-offset-default)',
106	          }}
107	        />
108	      )}
109	    </chakra.form>
110	  );
111	};
